#include <iostream>
#include <stdexcept>

class ScopeToken {
public:
    static int live;
    ScopeToken() { ++live; }
    ScopeToken(const ScopeToken&) = delete;
    ScopeToken& operator=(const ScopeToken&) = delete;
    ScopeToken(ScopeToken&&) = delete;
    ScopeToken& operator=(ScopeToken&&) = delete;
    ~ScopeToken() noexcept { --live; }
};
int ScopeToken::live = 0;

int main() {
    std::cout << ScopeToken::live << '\n';
    try {
        ScopeToken outer;
        std::cout << ScopeToken::live << '\n';
        {
            ScopeToken inner;
            std::cout << ScopeToken::live << '\n';
        }
        std::cout << ScopeToken::live << '\n';
        throw std::runtime_error("synthetic failure");
    } catch (const std::runtime_error&) {
        std::cout << ScopeToken::live << '\n';
    }
}

#include <iostream>
#include <memory>
#include <utility>

struct Position {
    int shares;
    static int destroyed;
    explicit Position(int value) : shares{value} {}
    ~Position() noexcept { ++destroyed; }
};
int Position::destroyed = 0;

int main() {
    std::cout << std::boolalpha;
    {
        auto owner = std::make_unique<Position>(7);
        Position* observer = owner.get();
        auto next_owner = std::move(owner);
        std::cout << (owner == nullptr) << '\n';
        std::cout << observer->shares << '\n';
        observer = nullptr; // Stop observing before destruction; aliases do not auto-null.
        next_owner.reset();
        std::cout << (next_owner == nullptr) << '\n';
        std::cout << Position::destroyed << '\n';
    }
    std::cout << Position::destroyed << '\n';
}
